import{_ as o,o as e,c as a,a2 as d}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"经济系统","description":"","frontmatter":{},"headers":[],"relativePath":"conomy.md","filePath":"conomy.md"}'),r={name:"conomy.md"};function l(n,t,i,s,c,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="经济系统" tabindex="-1">经济系统 <a class="header-anchor" href="#经济系统" aria-label="Permalink to &quot;经济系统&quot;">​</a></h1><p>服务器的通用货币是<strong>钻石</strong>。经济系统分为两个部分：</p><ul><li><strong>账户余额</strong>：记录在服务器数据中的数字，死亡不会掉落。</li><li><strong>背包钻石</strong>：以物品形态存在背包中的钻石，死亡会掉落。</li></ul><p>两者通过<strong>钻石银行</strong>互相转换。</p><h2 id="基础经济" tabindex="-1">基础经济 <a class="header-anchor" href="#基础经济" aria-label="Permalink to &quot;基础经济&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/money</code></td><td>查看自己的余额（别名 <code>/balance</code> <code>/bal</code>）</td></tr><tr><td><code>/baltop</code></td><td>查看全服富豪榜</td></tr><tr><td><code>/pay &lt;玩家&gt; &lt;金额&gt;</code></td><td>向其他玩家转账</td></tr><tr><td><code>/paytoggle</code></td><td>开关：是否接收别人向你转账</td></tr><tr><td><code>/payperm &lt;玩家&gt;</code></td><td>查看/管理对方是否允许收你的款</td></tr></tbody></table><p><strong>说明：</strong></p><ul><li>新玩家初始拥有 <strong>8 钻石</strong>。</li><li>交易时建议使用 <code>/pay</code> 转账而非把钻石丢在地上，避免损失。</li></ul><h2 id="钻石银行" tabindex="-1">钻石银行 <a class="header-anchor" href="#钻石银行" aria-label="Permalink to &quot;钻石银行&quot;">​</a></h2><p>钻石银行把「背包里的钻石」与「账户余额」互转，存进去更安全，取出来即可交易或使用。</p><table tabindex="0"><thead><tr><th>指令</th><th>作用</th></tr></thead><tbody><tr><td><code>/diamond</code></td><td>打开钻石银行界面（别名 <code>/bank</code>）</td></tr><tr><td><code>/diamond save &lt;数量&gt;</code></td><td>从背包存入钻石到账户</td></tr><tr><td><code>/diamond takeout &lt;数量&gt;</code></td><td>从账户取出钻石到背包</td></tr></tbody></table><p><strong>界面操作：</strong></p><ul><li>打开银行界面后，点击「存入」按钮放入钻石。</li><li>点击「取出」按钮提取账户余额为钻石。</li></ul><h2 id="赚钱方式" tabindex="-1">赚钱方式 <a class="header-anchor" href="#赚钱方式" aria-label="Permalink to &quot;赚钱方式&quot;">​</a></h2><ul><li><strong>挖矿</strong>：去主世界挖矿，钻石矿是最值钱的。</li><li><strong>交易</strong>：与玩家交易物品，或当面交换。</li><li><strong>生产</strong>：经营农场、刷怪塔出售物资。</li><li><strong>活动</strong>：参与服务器活动；宣传视频三连并截图进 QQ 群，可领取 <strong>32 钻石</strong>。</li></ul><h2 id="小提示" tabindex="-1">小提示 <a class="header-anchor" href="#小提示" aria-label="Permalink to &quot;小提示&quot;">​</a></h2><ul><li>随身只带少量钻石，大额放银行，避免死亡损失。</li><li>余额不会因死亡掉落，背包里的钻石会（详见 <a href="./teleport.html">传送系统</a> 与 <a href="./worlds.html">世界</a>）。</li></ul>',17)])])}const u=o(r,[["render",l]]);export{p as __pageData,u as default};
